---RefreshBoardByContent 根据标题和内容刷新提示板
---@param titleText string 标题文字
---@param contentText string 内容文字
---@param descText string 一段描述
---@param rare number
---@param id number 物品id
---@param isShowNumText boolean 是否显示数量
function CommonTipsBoardBuff:RefreshBoardByContent(titleText, contentText, rare, id ,isShowNumText, descText, uId)
	-- 标题
	local mb = GetLuaBehaviour(self.TitleNode.gameObject, TitleNodePath)
	if not isNull(mb) then
		if not KTool.IsNull(mb.Env) then
			---@type CommonTitleNode
			local env = mb.Env
			local goodsType = GoodsUtils.GetIdType(id)
			local iconPath = nil
			if goodsType == Constants.IDType.Equipment then
				iconPath = EquipUtils.GetEquipmentSetIcon(id)
			end
			env:RefreshUI(
					titleText, 
					nil,
					nil,
					nil,
					nil,
					iconPath
			)
		end
	end

	local descTitle = not string.isEmpty(contentText) and string.gsub(contentText, "\\n", "\n") or ""
	CfUtils.FillText(self.TitleTxt, descTitle)
	
	if not string.isEmpty(descText) then
		CfUtils.FillText(self.ContentTxt, descText)
	else
		---@type GoodsVo
		local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(id)
		if goodsVo then
			if string.isEmpty(goodsVo.description) then
				KTool.SetActive(self.ContentTxt, false)
			else
				CfUtils.FillText(self.TitleTxt, goodsVo.description)     --物品的直接强转
				CfUtils.FillText(self.ContentTxt, goodsVo.desc)
				KTool.SetActive(self.ContentTxt, true)
			end
		else
			KTool.SetActive(self.ContentTxt, false)
		end
	end
	
	KTool.SetActive(self.NumTxt, isShowNumText ~= nil and isShowNumText or false)
	KTool.SetActive(self.TextNumber, isShowNumText ~= nil and isShowNumText or false)
	if id ~= nil and isShowNumText == true then
		local amount = checkInt(GoodsUtils.GetThingNo(id))
		--self.NumTxt.text = string.format('%s:%s', localize('拥有'), amount)
		CfUtils.FillText(self.TextNumber, amount)
	end

	local goodsType = GoodsUtils.GetIdType(id)
	if goodsType == Constants.IDType.Equipment then
		CfUtils.SetActive(self.MainAttribute, true)
		CfUtils.FillText(self.TitleTxt, '')
		local equipVo = cardConfMgr:GetEquipVoById(id)
		local mainEquipAttrVo = cardConfMgr:GetEquipAttrVoById(equipVo.poolMain)
		local mainAttrVo = cardConfMgr:GetBasicAttrByBasicAttrAdditionId(mainEquipAttrVo.attrAdditionId)
		local attrAdditionVo = cardConfMgr:GetBasicAttrAdditionById(mainEquipAttrVo.attrAdditionId)
		local setVo = CfUtils.GetCfVo(AutoIds.IdSetting102, "EquipFilterVo", equipVo.suitId)
		
		CfUtils.FillText(self.MainAttrTitle, attrAdditionVo.attrAdditionName)
		CfUtils.FillImage(self.MainAttrIcon, mainAttrVo.icon)
		local attrNum = mainEquipAttrVo.attrNum[tostring(rare)]
		local attrStr = ''
		if checkInt(mainEquipAttrVo.isRandom) == 0 then
			attrStr = attribute_format(attrAdditionVo.isConversion, attrNum.baseMin)
		else
			attrStr = attribute_format(attrAdditionVo.isConversion, attrNum.baseMin) .. "-" .. attribute_format(attrAdditionVo.isConversion, attrNum.baseMax)
		end
		CfUtils.FillText(self.MainAttrTextNum, attrStr)
		CfUtils.SetActive(self.TitleTxt, false)
		CfUtils.SetActive(self.ContentTxt, false)
		CfUtils.SetActive(self.SuitDesc, true)
		CfUtils.FillText(self.TextSuitDesc, setVo.desc2)
		CfUtils.SetActive(self.StateGroup, false)
	else
		CfUtils.SetActive(self.MainAttribute, false)
		CfUtils.SetActive(self.TitleTxt, true)
		CfUtils.SetActive(self.SuitDesc, false)
		CfUtils.SetActive(self.ContentTxt, true)
		CfUtils.SetActive(self.StateGroup, true)
	end

	self:FillGoodsInfo(id, uId)
end

---RefreshBoardByContents 根据多标题和内容刷新提示板
---@param titleText string 标题文字
---@param contentTexts string 内容文字
---@param descTexts string 一段描述
---@param rare number
---@param id number 物品id
---@param isShowNumText boolean 是否显示数量
function CommonTipsBoardBuff:RefreshBoardByContents(titleText, contentTexts, rare, id ,isShowNumText, descTexts)
	-- 标题
	local mb = GetLuaBehaviour(self.TitleNode.gameObject, TitleNodePath)
	if not isNull(mb) then
		if not KTool.IsNull(mb.Env) then
			---@type CommonTitleNode
			local env = mb.Env
			env:RefreshUI(titleText, rare)
		end
	end
	KTool.SetActive(self.NumTxt, isShowNumText ~= nil and isShowNumText or false)
	KTool.SetActive(self.TextNumber, isShowNumText ~= nil and isShowNumText or false)

	if id ~= nil and isShowNumText == true then
		local amount = checkInt(GoodsUtils.GetThingNo(id))
		--self.NumTxt.text = string.format('%s:%s', localize('拥有'), amount)
		CfUtils.FillText(self.TextNumber, amount)
	end

	KTool.SetActive(self.TitleTxt, false)
	KTool.SetActive(self.ContentTxt, false)

	contentTexts = checkTable(contentTexts)
	descTexts = checkTable(descTexts)
	local count = math.max(table.count(contentTexts), table.count(descTexts))
	for i = 1, count do
		--先绘制标题
		local data = descTexts[i]
		if data then
			local go = CfUtils.InstantiateGo(self.TitleTxt, self.Bg)
			if go then
				CfUtils.FillText(go, string.gsub(checkString(data), "\\n", "\n"))
				KTool.SetActive(go, true)
			end
		end

		data = contentTexts[i]
		if data then
			local go = CfUtils.InstantiateGo(self.ContentTxt, self.Bg)
			if go then
				CfUtils.FillText(go, string.gsub(checkString(data), "\\n", "\n"))
				KTool.SetActive(go, true)
			end
		end
	end

	local go = self.Bg.transform:Find("ImgSymbolDown")
	if go then
		go.transform:SetAsLastSibling()
	end

	self:FillGoodsInfo(id)
end

function CommonTipsBoard:FillGoodsInfo(goodsId, uId)
	CfUtils.SetActive(self.GoodGroup, checkNumber(goodsId) > 0)
	if checkNumber(goodsId) <= 0 then
		return
	end

	CfUtils.RefeshGoodGo2(self.GoodNode, goodsId, nil, nil, nil, function()
        
    end, uId, {isTips = 1})

	local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
	local vo = CfUtils.GetCfVo(AutoIds.IdSetting4070, "GoodsShowTypeVo", goodsVo.showType)
	local isShowStar
	if vo then
		CfUtils.FillText(self.TxtMaterial, vo.name)
		isShowStar = (checkNumber(vo.showStar) == 1)
		CfUtils.SetActive(self.StarGroup, isShowStar)
		if isShowStar then
			local goodStar = self.GoodNode:Find("Container/Layout/GoodStar")
			if isNotNull(goodStar) then
				CfUtils.SetActive(goodStar, false)
			end
			local icon = self.GoodNode:Find("Container/Icon")
			if isNotNull(icon) then
				icon.transform.localPosition = Vector3.New(icon.transform.localPosition.x, icon.transform.localPosition.y - 18, icon.transform.localPosition.z)
			end
		end 
	else
		CfUtils.SetActive(self.StarGroup, false)
	end
    if isShowStar then
        local num = checkNumber(goodsVo.quality)
        for i = 1, num do
            local go = CfUtils.InstantiateGo(self.ImgStar, self.StarGroup)
            CfUtils.SetActive(go, true)
        end  
    end
end

function CommonTipsBoard:SetSkillMode()
	KTool.SetActive(self.GoodGroup, true)
	KTool.SetActive(self.StateGroup, false)
	local RT_Bg = self.GoodNode:Find("Container/Bg")
	if RT_Bg then
		KTool.SetActive(RT_Bg, false)
	end
	local RT_Icon = self.GoodNode:Find("Container/Icon")
	if RT_Icon then
		RT_Icon.localScale = Vector3.one * 1.7
		return RT_Icon:GetComponent(typeof(CS.UnityEngine.UI.RawImage))
	end
end

function CommonTipsBoard:SetCloseCallBack(handler)
	self.closeCallBack_ = handler
end
function CommonTipsBoard:GetCloseCallBack()
	return self.closeCallBack_
end

